import{_ as n,a0 as d,w as r,s as p,I as e,x as s,a1 as t,A as l,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"为初学者准备的 MariaDB 管理命令 | LCTT x X-CMD","titleTemplate":false,"description":"为初学者准备的 MariaDB 管理命令 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为初学者准备的 MariaDB 管理命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为初学者准备的 MariaDB 管理命令 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171202 MariaDB administration commands for beginners","title":"为初学者准备的 MariaDB 管理命令","tag":"201802","desc":""},"relativePath":"201802/20171202 MariaDB administration commands for beginners.md","filePath":"[post].md"}'),h={name:"201802/20171202 MariaDB administration commands for beginners.md"};function g(b,a,k,c,u,m){const i=d("Link");return r(),p("div",null,[a[19]||(a[19]=e("h1",{id:"为初学者准备的-mariadb-管理命令",tabindex:"-1"},[s("为初学者准备的 MariaDB 管理命令 "),e("a",{class:"header-anchor",href:"#为初学者准备的-mariadb-管理命令","aria-label":"Permalink to “为初学者准备的 MariaDB 管理命令”"},"​")],-1)),e("p",null,[a[1]||(a[1]=s("之前我们学过了",-1)),t(i,{href:"http://linuxtechlab.com/installing-configuring-mariadb-rhelcentos/"},{default:l(()=>[...a[0]||(a[0]=[s("在 Centos/RHEL 7 上安装 MariaDB 服务器并保证其安全",-1)])]),_:1}),a[2]||(a[2]=s("，使之成为了 RHEL/CentOS 7 的默认数据库。现在我们再来看看一些有用的 MariaDB 管理命令。这些都是使用 MariaDB 最基础的命令，而且它们对 MySQL 也同样适合，因为 Mariadb 就是 MySQL 的一个分支而已。",-1))]),e("p",null,[e("strong",null,[a[4]||(a[4]=s("(推荐阅读：",-1)),t(i,{href:"http://linuxtechlab.com/mongodb-installation-configuration-rhelcentos/"},{default:l(()=>[...a[3]||(a[3]=[s("在 RHEL/CentOS 上安装并配置 MongoDB",-1)])]),_:1}),a[5]||(a[5]=s(")",-1))])]),a[20]||(a[20]=o(`<h3 id="mariadb-管理命令" tabindex="-1">MariaDB 管理命令 <a class="header-anchor" href="#mariadb-管理命令" aria-label="Permalink to “MariaDB 管理命令”">​</a></h3><h4 id="_1、查看-mariadb-安装的版本" tabindex="-1">1、查看 MariaDB 安装的版本 <a class="header-anchor" href="#_1、查看-mariadb-安装的版本" aria-label="Permalink to “1、查看 MariaDB 安装的版本”">​</a></h4><p>要查看所安装数据库的当前版本，在终端中输入下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -version</span></span></code></pre></div><p>该命令会告诉你数据库的当前版本。此外你也可以运行下面命令来查看版本的详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqladmin -u root -p version</span></span></code></pre></div><h4 id="_2、登录-mariadb" tabindex="-1">2、登录 MariaDB <a class="header-anchor" href="#_2、登录-mariadb" aria-label="Permalink to “2、登录 MariaDB”">​</a></h4><p>要登录 MariaDB 服务器，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span></code></pre></div><p>然后输入密码登录。</p><h4 id="_3、列出所有的数据库" tabindex="-1">3、列出所有的数据库 <a class="header-anchor" href="#_3、列出所有的数据库" aria-label="Permalink to “3、列出所有的数据库”">​</a></h4><p>要列出 MariaDB 当前拥有的所有数据库，在你登录到 MariaDB 中后运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; show databases;</span></span></code></pre></div><p>（LCTT 译注：<code>$</code> 这里代表 shell 的提示符，<code>&gt;</code> 这里代表 MariaDB shell 的提示符。）</p><h4 id="_4、创建新数据库" tabindex="-1">4、创建新数据库 <a class="header-anchor" href="#_4、创建新数据库" aria-label="Permalink to “4、创建新数据库”">​</a></h4><p>在 MariaDB 中创建新数据库，登录 MariaDB 后运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; create database dan;</span></span></code></pre></div><p>若想直接在终端创建数据库，则运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqladmin -u user -p create dan</span></span></code></pre></div><p>这里，<code>dan</code> 就是新数据库的名称。</p><h4 id="_5、删除数据库" tabindex="-1">5、删除数据库 <a class="header-anchor" href="#_5、删除数据库" aria-label="Permalink to “5、删除数据库”">​</a></h4><p>要删除数据库，在已登录的 MariaDB 会话中运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; drop database dan;</span></span></code></pre></div><p>此外你也可以运行，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqladmin -u root -p drop dan</span></span></code></pre></div><p><strong>注意：</strong> 若在运行 <code>mysqladmin</code> 命令时提示 “access denied” 错误，这应该是由于我们没有给 root 授权。要对 root 授权，请参照第 7 点方法，只是要将用户改成 root。</p><h4 id="_6、创建新用户" tabindex="-1">6、创建新用户 <a class="header-anchor" href="#_6、创建新用户" aria-label="Permalink to “6、创建新用户”">​</a></h4><p>为数据库创建新用户，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; CREATE USER &#39;dan&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;password&#39;;</span></span></code></pre></div><h4 id="_7、授权用户访问某个数据库" tabindex="-1">7、授权用户访问某个数据库 <a class="header-anchor" href="#_7、授权用户访问某个数据库" aria-label="Permalink to “7、授权用户访问某个数据库”">​</a></h4><p>授权用户访问某个数据库，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; GRANT ALL PRIVILEGES ON test.* to &#39;dan&#39;@&#39;localhost&#39;;</span></span></code></pre></div><p>这会赋予用户 <code>dan</code> 对名为 <code>test</code> 的数据库完全操作的权限。我们也可以限定为用户只赋予 <code>SELECT</code>、<code>INSERT</code>、<code>DELETE</code> 权限。</p><p>要赋予访问所有数据库的权限，将 <code>test</code> 替换成 <code>*</code> 。像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; GRANT ALL PRIVILEGES ON *.* to &#39;dan&#39;@&#39;localhost&#39;;</span></span></code></pre></div><h4 id="_8、备份-导出数据库" tabindex="-1">8、备份/导出数据库 <a class="header-anchor" href="#_8、备份-导出数据库" aria-label="Permalink to “8、备份/导出数据库”">​</a></h4><p>要创建单个数据库的备份，在终端窗口中运行下列命令，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p database_name&gt;db_backup.sql</span></span></code></pre></div><p>若要一次性创建多个数据库的备份则运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p --databases db1 db2 &gt; db12_backup.sql</span></span></code></pre></div><p>要一次性导出多个数据库，则运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqldump -u root -p --all-databases &gt; all_dbs.sql</span></span></code></pre></div><h4 id="_9、从备份中恢复数据库" tabindex="-1">9、从备份中恢复数据库 <a class="header-anchor" href="#_9、从备份中恢复数据库" aria-label="Permalink to “9、从备份中恢复数据库”">​</a></h4><p>要从备份中恢复数据库，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p database_name &lt; db_backup.sql</span></span></code></pre></div><p>但这条命令成功的前提是预先没有存在同名的数据库。如果想要恢复数据库数据到已经存在的数据库中，则需要用到 <code>mysqlimport</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysqlimport -u root -p database_name &lt; db_backup.sql</span></span></code></pre></div><h4 id="_10、更改-mariadb-用户的密码" tabindex="-1">10、更改 mariadb 用户的密码 <a class="header-anchor" href="#_10、更改-mariadb-用户的密码" aria-label="Permalink to “10、更改 mariadb 用户的密码”">​</a></h4><p>本例中我们会修改 <code>root</code> 的密码，但修改其他用户的密码也是一样的过程。</p><p>登录 mariadb 并切换到 &#39;mysql&#39; 数据库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mysql -u root -p</span></span>
<span class="line"><span>&gt; use mysql;</span></span></code></pre></div><p>然后运行下面命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; update user set password=PASSWORD(&#39;your_new_password_here&#39;) where User=&#39;root&#39;;</span></span></code></pre></div><p>下一步，重新加载权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; flush privileges;</span></span></code></pre></div><p>然后退出会话。</p><p>我们的教程至此就结束了，在本教程中我们学习了一些有用的 MariaDB 管理命令。欢迎您的留言。</p><hr>`,58)),e("p",null,[a[7]||(a[7]=s("via: ",-1)),t(i,{href:"http://linuxtechlab.com/mariadb-administration-commands-beginners/"},{default:l(()=>[...a[6]||(a[6]=[s("http://linuxtechlab.com/mariadb-administration-commands-beginners/",-1)])]),_:1})]),e("p",null,[a[11]||(a[11]=s("作者：",-1)),t(i,{href:"http://linuxtechlab.com/author/shsuain/"},{default:l(()=>[...a[8]||(a[8]=[s("Shusain",-1)])]),_:1}),a[12]||(a[12]=s(" 译者：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[9]||(a[9]=[s("lujun9972",-1)])]),_:1}),a[13]||(a[13]=s(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...a[10]||(a[10]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[16]||(a[16]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[14]||(a[14]=[s("LCTT",-1)])]),_:1}),a[17]||(a[17]=s(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...a[15]||(a[15]=[s("Linux中国",-1)])]),_:1}),a[18]||(a[18]=s(" 荣誉推出",-1))])])}const x=n(h,[["render",g]]);export{C as __pageData,x as default};
